//! Register tables of the GPU classes, generated from NVIDIA's class headers in Mesa
//! (`mesa-nouveau/src/nouveau/headers/nvidia/classes/` in the reference folder, at the commit
//! pinned in `docs/references.md`). GPU protocol slice G3 (`docs/specs/gpu-protocol.md`, "Port
//! slices"); the owner chose generated tables over hand-written ones (that spec's decision 6).
//!
//! Each submodule is generated by `cargo xtask gen-classes` from one header and named after it.
//! It holds one constant per define, named as the header names it without the class prefix
//! (`NVC797_SET_OBJECT_CLASS_ID` is [`clc797::SET_OBJECT_CLASS_ID`]), and a `HEADER` table
//! ([`ClassHeader`]) that lists them all by name. The submodules are committed; never edit them
//! by hand. The gate's `classes` step regenerates them and fails on any difference when the
//! reference folder is present, and skips with a notice when it is not (CI has none).
//!
//! The types in this module are written by hand, and the generated modules build on them:
//!
//! - [`Method`]: a register in a class's method space, by byte address as the header gives it,
//!   with the strides of an array method. Method numbers (dword indices, as in
//!   [`crate::mme`] and the spec) come from [`Method::method`].
//! - [`Bits`]: where a field lives. A method's fields are single-word [`Field`]s; the fields of
//!   structures (the QMD, the texture header) are [`MwField`]s, counted in bits across the
//!   structure's words as the headers' `MW(high:low)` form is, or [`MwArray`]s of them.
//! - [`NamedField`], [`Value`]: a field with its named values, and a named number.
//!
//! What the headers do not say is not here: array lengths (Mesa keeps its own list in
//! `class_parser.py`), which methods hold floats, and which values are valid beyond the named
//! ones. The reading rules and how they differ from Mesa's own parser are in the generator's
//! docs (`xtask/src/gen_classes/parse.rs`).

#[rustfmt::skip]
pub mod cl902d;
#[rustfmt::skip]
pub mod cla140;
#[rustfmt::skip]
pub mod clc76f;
#[rustfmt::skip]
pub mod clc797;
#[rustfmt::skip]
pub mod clc797tex;
#[rustfmt::skip]
pub mod clc7b5;
#[rustfmt::skip]
pub mod clc7c0;
#[rustfmt::skip]
pub mod clc7c0qmd;

// Tests: `crates/gpu/tests/classes.rs` (everything in `classes/` is generated, and the gate
// treats any other file there as a stray).

use crate::field::Field;

/// Every generated header table, in the order of their module names.
pub const HEADERS: &[ClassHeader] = &[
    cl902d::HEADER,
    cla140::HEADER,
    clc76f::HEADER,
    clc797::HEADER,
    clc797tex::HEADER,
    clc7b5::HEADER,
    clc7c0::HEADER,
    clc7c0qmd::HEADER,
];

/// Everything generated from one class header.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ClassHeader {
    /// The header's file name (`clc797.h`).
    pub header: &'static str,
    /// The class id define, for a header that has one (the structure headers do not).
    pub class: Option<ClassId>,
    /// The methods, in the header's order.
    pub methods: &'static [Method],
    /// The fields that belong to no method (structure layouts), in the header's order.
    pub fields: &'static [NamedField],
    /// The numbers that are neither methods nor values of a field, in the header's order.
    pub constants: &'static [Value],
}

/// The define that names a class (`AMPERE_B`, `0xC797`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ClassId {
    /// The define's name.
    pub name: &'static str,
    /// The class number.
    pub id: u32,
}

/// A method of a class: a register in its method space.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Method {
    /// The header's name without the class prefix or index parameters.
    pub name: &'static str,
    /// The byte address, as the header gives it (of element 0 for an array). Always a multiple
    /// of 4: the generator refuses a header where it is not.
    pub byte_address: u32,
    /// For an array method, the byte stride of each index, in the order of the header's index
    /// parameters (`(i)`, or `(i,j)`); empty otherwise.
    pub strides: &'static [u32],
    /// The method's fields, in the header's order.
    pub fields: &'static [NamedField],
}

impl Method {
    /// The method number (dword index, byte address / 4) of the method, or of element 0 of an
    /// array.
    pub const fn method(&self) -> u32 {
        self.byte_address / 4
    }

    /// The byte address of the element at `indices`, one index per stride; `None` if the number
    /// of indices differs from the number of strides or the address overflows 32 bits. The
    /// headers give no array lengths, so the indices are not bounded otherwise.
    pub fn byte_address_at(&self, indices: &[u32]) -> Option<u32> {
        if indices.len() != self.strides.len() {
            return None;
        }
        self.strides
            .iter()
            .zip(indices)
            .try_fold(self.byte_address, |address, (stride, index)| {
                address.checked_add(stride.checked_mul(*index)?)
            })
    }

    /// The method number of the element at `indices` (see [`Method::byte_address_at`]).
    pub fn method_at(&self, indices: &[u32]) -> Option<u32> {
        self.byte_address_at(indices).map(|address| address / 4)
    }
}

/// A field and its named values.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct NamedField {
    /// For a method's field, the part of the header's name after the method's name
    /// (`CLASS_ID`); for a field of no method, the whole name without the class prefix.
    pub name: &'static str,
    /// Where the field lives.
    pub bits: Bits,
    /// The named values, in the header's order: the part of each name after the field's name.
    pub values: &'static [Value],
}

/// Where a field lives.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Bits {
    /// `high:low` within one 32-bit word.
    Word(Field),
    /// `MW(high:low)`: counted across the words of a structure.
    Multi(MwField),
    /// `MW((high+(i)*stride):(low+(i)*stride))`: an array of multi-word fields.
    MultiArray(MwArray),
}

/// A named number: a value of a field, or a constant.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Value {
    /// The name (see [`NamedField::values`] and [`ClassHeader::constants`]).
    pub name: &'static str,
    /// The number.
    pub value: u32,
}

/// The number of bits in a word of a structure.
const WORD_BITS: u32 = u32::BITS;

/// A bit field `MW(high:low)` (inclusive) of a structure of 32-bit words: bit `n` is bit
/// `n % 32` of word `n / 32`. At most 32 bits wide, so it spans at most two words.
///
/// Every operation is total: a field whose `high` is below its `low`, or that is wider than 32
/// bits, is invalid, and reading or writing it gives `None`, as does a field that ends past the
/// words given.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct MwField {
    high: u32,
    low: u32,
}

impl MwField {
    /// The field `MW(high:low)`, written as in NVIDIA's headers.
    pub const fn new(high: u32, low: u32) -> Self {
        Self { high, low }
    }

    /// The highest bit of the field.
    pub const fn high(self) -> u32 {
        self.high
    }

    /// The lowest bit of the field.
    pub const fn low(self) -> u32 {
        self.low
    }

    /// The number of bits in the field; `None` if the field is invalid (inverted, or wider
    /// than 32 bits).
    pub const fn width(self) -> Option<u32> {
        if self.high < self.low {
            return None;
        }
        let width = self.high - self.low + 1;
        if width > WORD_BITS { None } else { Some(width) }
    }

    /// The field's mask (unshifted) and the indices of its first and last words.
    fn layout(self) -> Option<(u64, usize, usize)> {
        let width = self.width()?;
        let mask = (1u64 << width) - 1;
        let first = usize::try_from(self.low / WORD_BITS).ok()?;
        let last = usize::try_from(self.high / WORD_BITS).ok()?;
        Some((mask, first, last))
    }

    /// The field's value in `words`; `None` if the field is invalid or ends past `words`.
    pub fn get(self, words: &[u32]) -> Option<u32> {
        let (mask, first, last) = self.layout()?;
        let low_word = u64::from(*words.get(first)?);
        let high_word = u64::from(*words.get(last)?);
        let joined = if last == first {
            low_word
        } else {
            low_word | (high_word << WORD_BITS)
        };
        let value = (joined >> (self.low % WORD_BITS)) & mask;
        u32::try_from(value).ok()
    }

    /// Replaces the field in `words` with `value`. Returns `None`, and changes nothing, if the
    /// field is invalid, ends past `words`, or `value` does not fit.
    pub fn insert(self, words: &mut [u32], value: u32) -> Option<()> {
        let (mask, first, last) = self.layout()?;
        if u64::from(value) & !mask != 0 || last >= words.len() {
            return None;
        }
        let shift = self.low % WORD_BITS;
        let mut joined = u64::from(words[first]);
        if last != first {
            joined |= u64::from(words[last]) << WORD_BITS;
        }
        joined = (joined & !(mask << shift)) | (u64::from(value) << shift);
        // The low half goes back to the first word, the high half (if the field spans two
        // words) to the second.
        let low_half = u32::try_from(joined & u64::from(u32::MAX)).ok()?;
        let high_half = u32::try_from(joined >> WORD_BITS).ok()?;
        words[first] = low_half;
        if last != first {
            words[last] = high_half;
        }
        Some(())
    }
}

/// An array of multi-word fields, `MW((high+(i)*stride):(low+(i)*stride))`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct MwArray {
    first: MwField,
    stride: u32,
}

impl MwArray {
    /// The array whose element 0 is `MW(high:low)` and whose elements are `stride` bits apart.
    pub const fn new(high: u32, low: u32, stride: u32) -> Self {
        Self {
            first: MwField::new(high, low),
            stride,
        }
    }

    /// The distance in bits between elements.
    pub const fn stride(self) -> u32 {
        self.stride
    }

    /// Element `index`; `None` if its bit positions overflow 32 bits. The headers give no
    /// array lengths, so the index is not bounded otherwise.
    pub const fn element(self, index: u32) -> Option<MwField> {
        let Some(offset) = self.stride.checked_mul(index) else {
            return None;
        };
        match (
            self.first.high.checked_add(offset),
            self.first.low.checked_add(offset),
        ) {
            (Some(high), Some(low)) => Some(MwField::new(high, low)),
            _ => None,
        }
    }
}
